-- Table: masterdata_product
-- Source: accounting_admin_db.sql (1. Master data)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS masterdata_product (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_code      VARCHAR(50)  NOT NULL UNIQUE,
    name              VARCHAR(150) NOT NULL,
    item_type         VARCHAR(20)  NOT NULL
                      CHECK (item_type IN ('goods', 'service')),
    category_id       BIGINT REFERENCES masterdata_product_category(id),
    base_uom_id       BIGINT NOT NULL REFERENCES masterdata_uom(id),
    secondary_uom_id  BIGINT REFERENCES masterdata_uom(id),
    conversion_rate   NUMERIC(18,6) NOT NULL DEFAULT 1 CHECK (conversion_rate > 0),
    weight_kg         NUMERIC(18,4) NOT NULL DEFAULT 0 CHECK (weight_kg >= 0),
    barcode           VARCHAR(100) UNIQUE,
    selling_price     NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (selling_price >= 0),
    cost_price        NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (cost_price >= 0),
    min_stock         NUMERIC(18,4) NOT NULL DEFAULT 0 CHECK (min_stock >= 0),
    description       TEXT,
    status            VARCHAR(20)  NOT NULL DEFAULT 'active'
                      CHECK (status IN ('active', 'inactive')),
    created_at        TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ  NOT NULL DEFAULT now()
);
